// Temporary: extract user requests + planner outputs for B-class cost rows.
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'

const ROOT = 'C:/Users/Administrator/.dsh/sessions'
const m = Buffer.from([0x28, 0xb5, 0x2f, 0xfd])

function readEvents(file) {
  const buf = fs.readFileSync(file)
  const offs = []
  let i = 0
  while ((i = buf.indexOf(m, i)) >= 0) { offs.push(i); i += 4 }
  offs.push(buf.length)
  const out = []
  for (let k = 0; k < offs.length - 1; k++) {
    let s
    try { s = zlib.zstdDecompressSync(buf.subarray(offs[k], offs[k + 1])).toString('utf8') } catch { continue }
    for (const line of s.split('\n')) {
      if (!line.trim()) continue
      try { out.push(JSON.parse(line)) } catch {}
    }
  }
  return out
}

function buildIndex() {
  const idx = new Map()
  for (const ws of fs.readdirSync(ROOT)) {
    const wp = path.join(ROOT, ws)
    let ds
    try { ds = fs.readdirSync(wp) } catch { continue }
    for (const d of ds) idx.set(d.replace(/^session-/, ''), path.join(wp, d, 'session.v4.jsonl.zstd'))
  }
  return idx
}

const targets = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const idx = buildIndex()
const results = []
for (const t of targets) {
  const file = idx.get(t.sess)
  if (!file) { results.push({ ...t, error: 'session file not found' }); continue }
  const evs = readEvents(file)
  const users = evs.filter((e) => e.type === 'user/message')
    .map((e) => ({
      seq: e.seq, time: e.time,
      kind: e.data?.source?.kind,
      text: (e.data?.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('\n'),
    }))
    .filter((u) => u.kind !== 'system' && u.text && !/^\s*\[/.test(u.text))
  results.push({ ...t, file, users, userCount: users.length, eventCount: evs.length })
}
fs.writeFileSync(process.argv[3], JSON.stringify(results, null, 1), 'utf8')
console.log('wrote', process.argv[3], results.length)
for (const r of results) console.log(r.sess.slice(0, 13), 'users=' + (r.userCount ?? 'ERR'), r.error || '')

