    userIndex: anchor ? users.indexOf(anchor) : null,
    userTotal: users.length,
    request: anchor ? anchor.text.slice(0, 1200) : null,
  })
}
fs.writeFileSync(process.argv[3], JSON.stringify(out, null, 1), 'utf8')
