  console.log((o.request || '<none>').slice(0, 400))
}

// Map each B-class cost row to nearest preceding REAL human request.
import fs from 'node:fs'

const NOISE = /^(\[cost-meter\]|\[build-gate\]|\[agent-guard\]|<openviking-context|Time sampled while|<available_skills>|<dynamic_tool_catalog>|\[File )/

const rows = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const out = []
for (const r of rows) {
  const users = r.users || []
  const tsMs = r.ts * 1000
  const human = users.filter((u) => {
    const t = (u.text || '').trim()
    if (!t) return false
    if (NOISE.test(t)) return false
    return true
  })
  const before = human.filter((u) => u.time <= tsMs)
  const anchor = before.length ? before[before.length - 1] : human[0]
  out.push({
    i: r.i, sess: r.sess.slice(0, 13), ts: r.ts, p: r.p, c: r.c,
    anchorSeq: anchor?.seq, anchorTime: anchor?.time,
    gapSec: anchor ? Math.round((tsMs - anchor.time) / 1000) : null,
    userIndex: anchor ? human.indexOf(anchor) : null,
    humanTotal: human.length,
    request: anchor ? anchor.text : null,
  })
}
fs.writeFileSync(process.argv[3], JSON.stringify(out, null, 1), 'utf8')
for (const o of out) {
  console.log(`\n=== [${o.i}] ${o.sess} p=${o.p} c=${o.c} gap=${o.gapSec}s human=${o.userIndex}/${o.humanTotal}`)
  console.log((o.request || '<none>').slice(0, 300).replace(/\n+/g, ' | '))
}

// Inspect user/message source kinds to distinguish real human turns from injections.
import fs from 'node:fs'

const data = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
for (const r of data) {
  const users = r.users || []
  console.log(`\n##### session ${r.sess} (${r.file})`)
  for (const u of users) {
    const t = (u.text || '').replace(/\n+/g, ' | ')
    console.log(`  seq=${u.seq} kind=${u.kind} len=${(u.text || '').length}`)
    console.log(`    ${t.slice(0, 200)}`)
  }
}

// Final: for each B-class row, anchor to kind=user turn, and extract the planner output around ts.
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'

const ROOT = 'C:/Users/Administrator/.dsh/sessions'
const M = Buffer.from([0x28, 0xb5, 0x2f, 0xfd])

function readEvents(file) {
  const buf = fs.readFileSync(file)
  const offs = []
  let i = 0
  while ((i = buf.indexOf(M, i)) >= 0) { offs.push(i); i += 4 }
  offs.push(buf.length)
  const out = []
  for (let k = 0; k < offs.length - 1; k++) {
    let s
    try { s = zlib.zstdDecompressSync(buf.subarray(offs[k], offs[k + 1])).toString('utf8') } catch { continue }
    for (const line of s.split('\n')) {
      if (!line.trim()) continue
      try { out.push(JSON.parse(line)) } catch {}
    }
  }
  return out
}

function buildIndex() {
  const idx = new Map()
  for (const ws of fs.readdirSync(ROOT)) {
    const wp = path.join(ROOT, ws)
    let ds
    try { ds = fs.readdirSync(wp) } catch { continue }
    for (const d of ds) idx.set(d.replace(/^session-/, ''), path.join(wp, d, 'session.v4.jsonl.zstd'))
  }
  return idx
}

const rows = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const idx = buildIndex()
const out = []
for (const r of rows) {
  const file = idx.get(r.sess)
  if (!file) { out.push({ ...r, error: 'no file' }); continue }
  const evs = readEvents(file)
  const human = evs.filter((e) => e.type === 'user/message' && e.data?.source?.kind === 'user')
    .map((e) => ({ seq: e.seq, time: e.time, text: (e.data?.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('\n') }))
  const tsMs = r.ts * 1000
  const before = human.filter((u) => u.time <= tsMs)
  const anchor = before.length ? before[before.length - 1] : human[0]

  // assistant messages right after anchor (the planner answer lives in the orchestrator call, not here),
  // so capture tool/call records for the orchestrator invoke around ts.
  const near = evs.filter((e) => e.type === 'tool/call' && Math.abs(e.time - tsMs) < 1000 * 900)
    .map((e) => ({ seq: e.seq, time: e.time, name: e.data?.name, args: String(e.data?.arguments || '').slice(0, 220) }))
  const orchCalls = near.filter((c) => /orchestrate/.test(c.name || '') || /"op"\s*:/.test(c.args || ''))

  out.push({
    i: r.i, sess: r.sess, p: r.p, c: r.c, ts: r.ts,
    anchorSeq: anchor?.seq, gapSec: anchor ? Math.round((tsMs - anchor.time) / 1000) : null,
    humanTurns: human.map((u) => ({ seq: u.seq, time: u.time, text: u.text.slice(0, 500) })),
    request: anchor ? anchor.text : null,
    orchardCalls: orchCalls,
  })
}
fs.writeFileSync(process.argv[3], JSON.stringify(out, null, 1), 'utf8')
for (const o of out) {
  console.log(`\n=== [${o.i}] ${o.sess.slice(0, 13)} p=${o.p} c=${o.c} gap=${o.gapSec}s anchorSeq=${o.anchorSeq} humanTurns=${o.humanTurns?.length}`)
  console.log('REQ: ' + (o.request || '<none>').replace(/\n+/g, ' | ').slice(0, 500))
}

