// For each B-class row: find orchestrate tool/result nearest after ts, dump its text.
import fs from 'node:fs'
import path from 'node:path'
import zlib from 'node:zlib'

const ROOT = 'C:/Users/Administrator/.dsh/sessions'
const M = Buffer.from([0x28, 0xb5, 0x2f, 0xfd])
function readEvents(file) {
  const buf = fs.readFileSync(file)
  const offs = []
  let i = 0
  while ((i = buf.indexOf(M, i)) >= 0) { offs.push(i); i += 4 }
  offs.push(buf.length)
  const out = []
  for (let k = 0; k < offs.length - 1; k++) {
    let s
    try { s = zlib.zstdDecompressSync(buf.subarray(offs[k], offs[k + 1])).toString('utf8') } catch { continue }
    for (const line of s.split('\n')) { if (!line.trim()) continue; try { out.push(JSON.parse(line)) } catch {} }
  }
  return out
}
function buildIndex() {
  const idx = new Map()
  for (const ws of fs.readdirSync(ROOT)) {
    const wp = path.join(ROOT, ws)
    let ds; try { ds = fs.readdirSync(wp) } catch { continue }
    for (const d of ds) idx.set(d.replace(/^session-/, ''), path.join(wp, d, 'session.v4.jsonl.zstd'))
  }
  return idx
}

const rows = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const idx = buildIndex()
const cache = new Map()
const out = []
for (const r of rows) {
  const file = idx.get(r.sess)
  if (!file) { out.push({ ...r, error: 'no file' }); continue }
  if (!cache.has(file)) cache.set(file, readEvents(file))
  const evs = cache.get(file)
  const tsMs = r.ts * 1000
  const results = evs.filter((e) => e.type === 'tool/result')
  // pick result whose time >= ts and is closest
  const after = results.filter((e) => e.time >= tsMs).sort((a, b) => a.time - b.time)
  const pick = after[0] || results.filter((e) => e.time < tsMs).sort((a, b) => b.time - a.time)[0]
  let text = ''
  if (pick) {
    const c = pick.data?.message?.content || []
    text = c.filter((x) => x.type === 'text').map((x) => x.text).join('\n')
  }
  out.push({ i: r.i, sess: r.sess, p: r.p, c: r.c, ts: r.ts,
    resultSeq: pick?.seq, resultTime: pick?.time,
    deltaSec: pick ? Math.round((pick.time - tsMs) / 1000) : null,
    resultLen: text.length, resultText: text.slice(0, 4000) })
}
fs.writeFileSync(process.argv[3], JSON.stringify(out, null, 1), 'utf8')
for (const o of out) console.log(`[${o.i}] ${o.sess.slice(0,13)} p=${o.p} c=${o.c} resultSeq=${o.resultSeq} delta=${o.deltaSec}s len=${o.resultLen}`)

